ProjectALife.DialogueShards["scenes_any_16"] = {
{"s1_c02_soldier_canteen_025","any",3,"reg=civilian|tmp=fresh|day=2,10|mood=sad|world=vehicle",{1,"There's a soldier in the Hardins' yard, just the one - no truck",2,"Is he, you know - one of them?",1,"He asked for water - real polite, then he asked had we seen anybody from his unit",3,"And you said?",1,"Said no, he said okay, thank you ma'am, and walked off toward the tracks with his canteen"}},
{"s1_c02_clerk_in_germany_026","any",2,"reg=civilian|tmp=fresh|day=3,12|mood=calm",{1,"You were in the Army, just tell me yes or no - are they coming?",2,"Two years as a clerk in Germany - I typed, I don't know one thing the TV doesn't",1,"Then guess",2,"My guess is don't plan around it, plan like they're coming around Christmas"}},
{"s1_c02_two_xs_027","any",3,"reg=civilian|tmp=fresh|day=1,6|mood=funny|world=cars",{1,"Went by the Guard armory in {town} - gate's chained, trucks are gone",2,"Gone where?",1,"Cardboard sign on the gate says report to Fort Knox - somebody spelled Knox with two X's",3,"Well, that's a load off my mind"}},
{"s1_c02_larry_ladder_028","any",2,"reg=family|tmp=fresh|day=1,10|hour=21,4|mood=fear|world=door,stairs,road",{1,"It's Larry from across the street banging on the door - says he's returning our ladder",2,"Our ladder? He borrowed that ladder on Memorial Day",1,"He's got it with him, he's holding it up to the peephole so I can see",2,"Nobody returns a ladder at midnight, he wants in",1,"Well, he did bring the ladder"}},
{"s1_c02_six_inches_029","any",2,"reg=family|tmp=fresh|day=1,10|mood=angry|world=door,fence,inside",{1,"It's Wendell Burris, at the back door",2,"Wendell Burris took us to small claims over six inches of fence line",1,"He's got his grandbaby with him",2,"Six inches, two years of court dates",1,"I'm opening the door",2,"I know you are, tell him the six inches is his, now tell him to get in here"}},
{"s1_c02_petrie_steps_030","any",2,"reg=family|tmp=fresh|day=1,6|mood=sad",{1,"The Petrie girl is sitting on her front steps again - by herself",2,"Her folks both work second shift at the plant in Elizabethtown",1,"Second shift was Friday",2,"Go get her, and bring her school backpack too, so she's got her own things"}},
{"s1_c02_hunting_vest_meeting_031","any",3,"reg=civilian|tmp=fresh|day=2,10|mood=calm|world=road",{1,"Gary Tuttle once called a street meeting in his carport. Wore his orange hunting vest",2,"A meeting for what?",1,"Watch rotations, and a head count of every house on the street",3,"Gary couldn't run the church bake sale, his wife had to take it off him",1,"Nobody else was trying. That's why I went"}},
{"s1_c02_insulin_rent_032","any",2,"reg=civilian|tmp=fresh|day=2,8|mood=warm|world=building",{1,"Mrs. Albright next door asked can she keep her insulin in our cooler - we've still got ice",2,"How much room does it take?",1,"Six little bottles, she brought a tin of pecan sandies to pay rent on the space",2,"Tell her the whole top shelf is hers, and keep the pecan sandies"}},
{"s1_c02_dale_driveway_033","any",3,"reg=civilian|tmp=fresh|day=1,10|hour=20,3|mood=fear|world=vehicle",{1,"Remember Dale getting drunk and hollering our names from his driveway?",2,"I worried the shouting would bring trouble",1,"His wife had left for her mother's. He drank from the moment the car pulled out",3,"Somebody ought to have sat with him before it got that bad",2,"Water and somebody listening would have been a better start than us yelling back"}},
{"s1_c02_which_window_034","any",2,"reg=family|tmp=fresh|day=1,12|mood=fear|world=window,building",{1,"Who was that pounding?",2,"Ricky from next door, came to tell us there's one at our back window - then he ran home",1,"Which back window?",2,"He didn't say which, he was running"}},
{"s1_c02_chainsaw_trade_035","any",3,"reg=civilian|tmp=fresh|day=3,12|world=door,trees,road",{1,"Man at the door wants to trade a chainsaw for four cans of food",2,"What would we do with a chainsaw?",1,"Cut firewood, drop a tree across the road",3,"Pull that cord one time and every one of them in {town} comes to see what's running",2,"Give him two cans, put the saw in the shed and nobody touches it"}},
{"s1_c02_bring_the_dog_036","any",2,"reg=civilian|tmp=fresh|day=2,10|mood=warm|world=building",{1,"They'll come in, but they want to bring the dog",2,"That dog barks at wind, it barked at the mailman every day for six years",1,"She says then she'll stay out on the porch with him",2,"Nobody's sleeping on any porch - bring them in - bring the dog, we'll work out the barking"}},
{"s1_c02_sample_case_037","any",2,"reg=civilian|tmp=fresh|day=2,12|mood=grim|world=building",{1,"There's a woman standing on the porch holding a sample case",2,"That's Joyce, the Avon lady - she comes every other Thursday",1,"Is it Thursday?",2,"Don't open it! Look at her stockings, look at her leg"}},
{"s1_c02_mutter_four_knocks_038","any",1,"reg=civilian,family|tmp=fresh|day=1,14|hour=21,4|mood=fear",{1,"Four knocks - wait, four knocks again",1,"Too even for a person, a person gets tired of knocking",1,"Four more - okay, I'm not getting up - I'm not"}},
{"s1_c02_mutter_lynette_couch_039","any",1,"reg=civilian|tmp=fresh|day=2,10|mood=calm|world=water,road",{1,"Out past the high school, left at the grain elevator, gravel down to the river",1,"River road north, then the bridge - then I don't know",1,"Lynette's, then her couch, and I got no plan after that"}},
{"s1_c02_cotton_candy_040","any",3,"reg=civilian|tmp=fresh|day=2,8|mood=funny",{1,"Man on the CB said Louisville's holding - Downtown's fenced off, lights on, National Guard on every corner",2,"What was his handle?",1,"Cotton Candy, something like that",3,"A grown man calling himself Cotton Candy on a CB, I don't take his word on a whole city"}},
{"s1_c02_buses_tomorrow_041","any",3,"reg=civilian|tmp=fresh|day=1,5|world=cars,road",{1,"They say there's buses coming to the Methodist church lot at noon - taking people up to Louisville",2,"Who says?",1,"Everybody, it's all up and down the street",3,"I walked over there at noon yesterday, forty people and a dog, sitting on suitcases",2,"And the buses?",3,"Everybody said tomorrow"}},
{"s1_c02_bridge_lights_hill_042","any",2,"reg=civilian,family|tmp=fresh|day=3,12|hour=20,2|mood=sad",{1,"From the hill behind the church you can see the bridge lights - Louisville's still got power",2,"So they're alright up there",1,"Lights don't mean people, lights just mean the power plant hasn't heard yet"}},
{"s1_c02_tape_measure_043","any",2,"reg=family|tmp=fresh|day=2,10|mood=grim|world=window",{1,"Are we going to Louisville or not? Just say it",2,"Hand me that tape measure",1,"Russ",2,"I'm measuring the front window for plywood, hand me the tape",1,"So we're staying"}},
{"s1_c02_mutter_birth_certificates_044","any",1,"reg=family|tmp=fresh|day=1,8|mood=fear",{1,"Diapers - children's Tylenol, mama's heart pills, the whole bottle",1,"Birth certificates - why on earth do I need birth certificates?",1,"Because somebody at a folding table's gonna ask, put them in, just put them in"}},
{"s1_c02_travis_truck_045","any",3,"reg=family|tmp=fresh|day=2,12|hour=16,5|mood=angry|world=building",{1,"Y'all can sit here, me and Travis are taking his truck to Louisville tonight",2,"Travis is sixteen and he's wrecked that truck twice",1,"Once, the other time was a deer",3,"Nobody is taking anything anywhere - go to your room",1,"My room is a mattress in the hallway!",3,"Then go to your mattress"}},
{"s1_c02_little_bit_ten_four_046","any",2,"reg=family|tmp=fresh|day=1,8|mood=warm|world=vehicle,water",{1,"Uncle Pete's on the CB from his rig, he's parked at a truck stop across the river in Indiana",2,"Is he coming?",1,"He can't, the bridges are shut - he said to tell you to mind your mama",2,"Tell him I am",1,"He heard you, he says ten-four, little bit"}},
{"s1_c02_haskins_ham_047","any",2,"reg=civilian,family|tmp=fresh|day=2,10|mood=sad",{1,"The Haskins are leaving for Louisville, they brought over everything out of their fridge",2,"Half a ham, a jar of pickles, and three Cokes",1,"Mary said they'll get it back when they come home - said it like a loan",2,"Then write it down on the pad, half a ham, owed to the Haskins"}},
{"s1_c02_valley_station_traffic_048","any",2,"reg=civilian|tmp=fresh|day=3,14|mood=grim",{1,"If it's coming for me anyway, I'd sooner it came in my own kitchen than in a traffic jam in Valley Station",2,"It's not coming for anybody who stays smart",1,"Every one that got bit was being smart right up until they weren't",2,"Then be smart one more day, that's all I'm asking you - one more"}},
{"s1_c02_week_five_blisters_049","any",2,"reg=family|tmp=fresh|day=1,12|mood=warm|world=fence",{1,"Kyle's at Fort Knox - basic training - week five",2,"Then he's safer than any of us, he's got the whole Army around him",1,"His letter came Thursday, said the food's awful and his boots gave him blisters",2,"Then he's eating awful food with blisters on his feet - behind a fence, with a rifle",1,"Say it one more time"}},
{"s1_c02_oakes_linda_050","any",2,"reg=family|tmp=fresh|day=1,8|hour=21,4|mood=sad|world=door,road",{1,"It's Mr. Oakes, I can hear him, he's saying Linda, Linda, open up",2,"Linda's his wife, she's not here",1,"Then why is he saying her name at our door?",2,"Because he's said it at every door on this street since midnight - come away from there"}},
{"s1_c02_channel_three_051","any",2,"reg=family|tmp=fresh|day=5,12|mood=sad|world=generator",{1,"Want me to turn the TV off?",2,"Leave it, it's just static",1,"It's running off the generator",2,"Then turn it off, but leave the dial on channel three - that's where the news was"}},
{"s1_c02_buttercup_note_052","any",2,"reg=family|tmp=fresh|day=1,8|mood=sad|world=door",{1,"We can't take the goats, and we can't take the chickens",2,"Open the pen, let them take their chances",1,"Molly wants to tape a note to the barn door for whoever finds them - with all their names",2,"Let her, and help her spell Buttercup"}},
{"s1_c03_tackle_box_001","any",2,"reg=family|tmp=fresh|day=0,6|mood=sad|world=door,building",{1,"He's talking through the bathroom door, he wants me to write something down",2,"What?",1,"The life insurance papers are in the green tackle box - under the top tray, under the lures",2,"Get a pen, then, write it down exactly how he says it"}},
{"s1_c03_mutter_light_bill_002","any",1,"reg=family|tmp=fresh|day=0,6|mood=sad|world=vehicle,window",{1,"Truck goes to Wayne, he needs a truck worse than anybody",1,"Light bill's due the twentieth, somebody pay it at the courthouse window if they ever open back up",1,"I think that's everything - is that everything?"}},
{"s1_c03_not_mom_003","any",2,"reg=family|tmp=fresh|day=1,10|mood=fear",{1,"If it happens to me, you do it - not Mom",2,"Don't say that",1,"Promise, she'd carry it around forever, you're mean enough, you'll be fine",2,"I'm not mean",1,"You hid my Nintendo for a whole month in fourth grade - you'll be fine"}},
{"s1_c03_drive_for_ice_004","any",2,"reg=family|tmp=fresh|day=0,8|mood=grim",{1,"Take the kids for a drive, tell them we need ice from the gas station",2,"There's no ice anywhere in this county",1,"Then drive slow looking for it - be gone an hour - don't come back before an hour",2,"What are you going to do?",1,"Mama asked me to, it's between me and Mama"}},
{"s1_c03_pine_sol_floor_005","any",2,"reg=family|tmp=fresh|day=1,14|mood=sad|world=building",{1,"Why does the kitchen floor smell like Pine-Sol?",2,"Because I mopped it, baby",1,"You only mop on Saturdays",2,"I mopped today - go put your shoes on, we're eating out on the porch"}},
{"s1_c03_tomato_cages_006","any",2,"reg=family|tmp=fresh|day=1,10|mood=grim",{1,"Uncle Dwight once went out digging by the tomato cages",2,"Digging what?",1,"Said he'd rather do it while his arm still worked. Said it was his hole",2,"I wanted to take him water. Couldn't think of a thing to say"}},
{"s1_c03_posthole_digger_007","any",2,"reg=family|tmp=fresh|day=1,6|mood=grim|world=rain",{1,"We can't leave him on the den floor under a blanket - not in this heat",2,"Ground out back is hard as brick, no rain in two weeks",1,"The Sizemores have a posthole digger",2,"You can't dig a grave with a posthole digger",1,"You can now - go over and ask - ask them nice"}},
{"s1_c03_keyhole_humming_008","any",2,"reg=family|tmp=fresh|day=1,8|hour=19,3|mood=sad",{1,"Stop talking to her through the keyhole",2,"She hums back sometimes, when I say her name",1,"That's not humming",2,"It is to me - leave me be a little while longer"}},
{"s1_c03_pepper_growls_009","any",2,"reg=family|tmp=fresh|day=0,6|mood=fear|world=vehicle",{1,"Pepper once wouldn't stop growling at Grandpa",2,"Never growled at him before. He'd raised her from a pup",1,"He blamed the bandage, said she didn't like the peroxide smell",2,"Didn't know what it meant. We kept our distance instead of treating a dog's growl like a diagnosis"}},
{"s1_c03_oven_mitts_010","any",2,"reg=family|tmp=fresh|day=1,10|hour=16,5|mood=fear|world=building",{1,"Sit down, Irene, let somebody else cook tonight",2,"I've cooked for this family thirty-one years, a scratch on my hand isn't stopping supper",1,"You're wearing oven mitts, it's ninety degrees and the stove's not even on yet",2,"Then nobody has to look at the hand - go set the table"}},
{"s1_c03_mutter_start_there_011","any",1,"reg=family|tmp=fresh|day=0,10|mood=sad",{1,"Daddy has to go to the hospital for a while - no, the hospital's where it all started",1,"Daddy has to go help the Army, they'd believe that",1,"Daddy loves you, just start with that one - start there"}},
{"s1_c03_shed_ballgame_012","any",2,"reg=family|tmp=fresh|day=1,10|mood=sad",{1,"He's in the shed with a lawn chair, a jug of water, and his transistor",2,"Is he locked in?",1,"He locked himself in, handed me the key through the gap, said there's a ballgame on at seven",2,"There's no ballgame on anywhere",1,"He knows"}},
{"s1_c03_nails_on_floor_013","any",3,"reg=family|tmp=fresh|day=2,12|mood=fear|world=door,building",{1,"Who opened the bedroom door? I nailed that door shut",2,"Nobody opened it",1,"The nails are lying on the hall rug",3,"It was me, she wanted water, she sounded just like herself",1,"She hasn't been herself since Saturday!",3,"I know it, I know it now"}},
{"s1_c03_left_handed_fork_014","any",2,"reg=family|tmp=fresh|day=2,14|hour=16,20|mood=sad",{1,"Lacey set a plate for her daddy again",2,"Did you pick it up?",1,"No, she put his fork on the wrong side, the way he likes it - he's left-handed",2,"Leave it, then"}},
{"s1_c03_beep_daddy_015","any",2,"reg=family|tmp=fresh|day=1,8|mood=sad",{1,"Can we beep Daddy? You know his beeper number",2,"The phones don't work, bug",1,"Then how does he know we're okay?",2,"He'll have to guess we are, and we are, so he'll guess right"}},
{"s1_c03_penny_on_map_016","any",2,"reg=family|tmp=fresh|day=1,12|hour=4,11|mood=warm",{1,"Daddy's rig left Thursday for Memphis, he'd be headed back by now",2,"Show me on the map",1,"Here's Memphis, here's the interstate - I moved the penny up to Nashville this morning",2,"Where does the penny go tomorrow?",1,"Bowling Green, then he's close"}},
{"s1_c03_feed_store_cap_017","any",2,"reg=family|tmp=fresh|day=2,14|mood=warm",{1,"He's wearing his dad's feed store cap, it comes down past his eyebrows",2,"Stuff some newspaper in the band",1,"I did, he pulled it out, says it's supposed to be big, that's how you grow into it"}},
{"s1_c03_jiggles_knobs_018","any",2,"reg=family|tmp=fresh|day=2,14|hour=20,23|mood=sad|world=door",{1,"Luke's going around jiggling every doorknob twice before bed",2,"That's what his daddy did - every night - twice",1,"He did the back door three times tonight",2,"Then he's worried about the back door - let him"}},
{"s1_c03_garage_opener_019","any",2,"reg=family|tmp=fresh|day=5,14|mood=sad|world=door,building",{1,"Why is the garage door opener sitting on the kitchen counter?",2,"Abby put it there, so her daddy can get in without knocking",1,"Power's been out two days, it doesn't open anything",2,"She doesn't know that - leave it right where she put it"}},
{"s1_c03_saw_his_truck_020","any",2,"reg=family|tmp=fresh|day=3,14|mood=grim|world=door",{1,"Just tell me if you saw it happen - I'm fifteen - tell me",2,"I didn't see it",1,"Mom",2,"I saw his truck on the shoulder by the feed mill, door hanging open, that's all I know",1,"Thank you... really"}},
{"s1_c03_coconut_cream_021","any",2,"reg=family|tmp=fresh|day=2,12|hour=16,20|mood=sad",{1,"Is Daddy hungry wherever he is?",2,"I bet he found a diner, your daddy can find a diner anywhere",1,"With pie?",2,"With pie - coconut cream, now eat your crackers"}},
{"s1_c03_treehouse_wall_022","any",2,"reg=family|tmp=fresh|day=2,14|mood=angry|world=building",{1,"Owen kicked a hole in the hallway wall",2,"Is he hurt?",1,"No, he said his dad promised to finish the treehouse this weekend - he promised",2,"Did you tell him it's not his dad's fault?",1,"I told him, he kicked the wall again"}},
{"s1_c03_end_of_driveway_023","any",2,"reg=family|tmp=fresh|day=1,8|hour=15,18|mood=sad|world=vehicle,building",{1,"Four o'clock, she's out at the end of the driveway again",2,"Waiting on the car?",1,"His shift let out at three-thirty, the car turned in at four, every weekday for six years",2,"Go stand with her, take the bat, and go stand with her"}},
{"s1_c03_dragon_voice_024","any",2,"reg=family|tmp=fresh|day=2,14|hour=19,23|mood=warm",{1,"Dad does the voices when he reads, you don't do the voices",2,"I can do voices",1,"Do the dragon, then",2,"Rrrraaahh",1,"That's just you yawning - read it regular"}},
{"s1_c03_flag_down_025","any",2,"reg=family|tmp=fresh|day=3,14|mood=warm|world=building",{1,"Emma writes her daddy a letter every day, she wants them mailed",2,"Where are you putting them?",1,"In the mailbox, with the red flag up, it's been up since Monday",2,"Nobody's coming to get them",1,"I know, I sneak out at night and take them, she checks in the morning and the flag's down"}},
{"s1_c03_three_questions_026","any",2,"reg=family|tmp=fresh|day=4,14|mood=sad",{1,"New rule, three questions about Daddy a day, then we talk about something else",2,"That's not fair",1,"You've used two already, and it's nine o'clock in the morning",2,"Is he coming home today?",1,"That's three, baby"}},
{"s1_c03_c_batteries_027","any",2,"reg=civilian|tmp=fresh|day=3,14|mood=grim",{1,"Lost Dennis on Saturday, and his brother Sunday, they went back for their mother",2,"I'm sorry",1,"Does that radio take C batteries or D? I found a pack of C's in the glovebox"}},
{"s1_c03_pink_curlers_028","any",2,"reg=family|tmp=fresh|day=2,14|mood=sad",{1,"Mama still had her curlers in when it happened, the pink ones",2,"You don't need to say it, hon",1,"I'm not telling it, I just keep thinking about the curlers, somebody oughta take them out"}},
{"s1_c03_ex_husband_029","any",2,"reg=civilian|tmp=fresh|day=3,14|mood=sad",{1,"Only good thing in all this, my ex-husband lives in Louisville",2,"That's awful",1,"Heh - I know, I know it is",2,"Did he get out, you think?",1,"I don't know, I'd like to know, actually - isn't that something"}},
{"s1_c03_brothers_name_030","any",2,"reg=family|tmp=fresh|day=3,14|mood=sad",{1,"I called Josh by his brother's name at breakfast",2,"Happens, it happened before any of this",1,"He answered to it, just said yes ma'am and passed me the salt"}},
{"s1_c03_little_nip_031","any",2,"reg=civilian|tmp=fresh|day=1,10|mood=funny",{1,"Got nipped on the thumb dragging old man Crowe off his porch - real little nip, hahaha!",2,"You wash it?",1,"Washed it, poured whiskey on it, prayed over it, covered all my bases",2,"Grab the other end of this board"}},
{"s1_c03_sardines_van_032","any",2,"reg=family|tmp=fresh|day=1,10|hour=20,4|mood=fear|world=vehicle,door,window",{1,"We should sleep in the van tonight, doors locked, keys in the ignition",2,"It'll be ninety degrees in that van with the windows up",1,"And if they get in the house, we're already gone",2,"And if they get all around the van, we're sardines - I'll take my chances with the house"}},
{"s1_c03_mutter_least_warm_033","any",1,"reg=family|tmp=fresh|day=1,8|hour=0,5|mood=sad|world=door",{1,"Grandpa, it's Jodie, I brought you a Coke - I'm setting it by the door",1,"You can't open cans anymore, can you?",1,"I'm leaving it anyway, it's the cold one - well, the least warm one"}},
{"s1_c03_forty_minutes_water_034","any",2,"reg=family|tmp=fresh|day=0,2|mood=fear|world=building",{1,"He's been in the bathroom forty minutes with the water running",2,"Maybe he's washing it out",1,"Nobody washes anything for forty minutes",2,"Knock",1,"You knock"}},
{"s1_c03_church_directory_035","any",2,"reg=family|tmp=fresh|day=2,14|mood=sad",{1,"The only picture I grabbed of Dana is the one out of the church directory",2,"The one where she had the cold sore?",1,"She made me promise to ask the church to leave her out of the next directory - I never asked"}},
{"s1_c03_juicy_fruit_036","any",2,"reg=family|tmp=fresh|day=0,6|mood=sad|world=fence",{1,"Did Daddy shoot Mr. Wiley?",2,"Mr. Wiley was sick, sweetheart - real sick",1,"He used to hand me Juicy Fruit over the fence",2,"I know he did",1,"Can I still chew the pack he gave me? It's in my drawer"}},
{"s1_c03_washboard_037","any",2,"reg=family|tmp=fresh|day=3,14|mood=sad|world=building",{1,"You haven't cried, not one time since Friday",2,"Somebody has to do the wash",1,"You can cry and do the wash",2,"Not in this house, I can't, the kids can hear everything over the washboard"}},
{"s1_c03_neatsfoot_glove_038","any",2,"reg=family|tmp=fresh|day=2,14|hour=20,6|mood=sad",{1,"Cody slept with his ball glove on again",2,"The one his daddy oiled for him?",1,"Says it still smells like him - Neatsfoot oil and Winstons"}},
{"s1_c03_mutter_by_sevens_039","any",1,"reg=family|tmp=fresh|day=2,14|hour=21,4|mood=fear",{1,"Dad said if I ever got scared, count backwards from a hundred by sevens",1,"Hundred - ninety-three - eighty-six - seventy-nine",1,"He never said what you do when you run out of numbers"}},
{"s1_c03_check_front_door_040","any",3,"reg=family|tmp=fresh|day=1,10|hour=16,5|mood=grim|world=door",{1,"It's done, he's covered up in the back room",2,"Was he, at the end, did he know you?",1,"It was fast - don't ask me any more tonight",3,"I'll go check the front door"}},
{"s1_c03_through_the_window_041","any",2,"reg=family|tmp=fresh|day=0,8|mood=sad|world=window",{1,"He wants to see the kids, one more time, through the window",2,"They'll remember it",1,"They'll remember not getting to, too",2,"Then he washes his face first, and a clean shirt - and we pull the blind halfway"}},
{"s1_c03_nosebleed_042","any",2,"reg=family|tmp=fresh|day=1,14|hour=0,7|mood=fear",{1,"There's blood all over his pillow!",2,"He gets nosebleeds, he's had nosebleeds since he was three, it's the heat",1,"Wake him up",2,"Wake him up gentle - Mason - Mason, bud, you're alright, look at me"}},
{"s1_c03_same_hat_043","any",2,"reg=family|tmp=fresh|day=1,5|mood=sad",{1,"I saw Daddy on the news! In the crowd behind the soldiers!",2,"Honey, that was in Louisville",1,"He had on the same hat",2,"Lots of men have that hat",1,"Can we play the tape back again? To check?"}},
{"s1_c03_kitchen_dream_044","any",2,"reg=family|tmp=fresh|day=2,14|hour=0,5|mood=warm|world=building",{1,"Mama? I had the dream again, the one with the kitchen",2,"Come here, get in",1,"Is the kitchen part real?",2,"The kitchen's all clean now, I cleaned it myself - you want to go look at it?",1,"No, just stay awake till I'm asleep"}},
{"s1_c03_snow_shovel_045","any",3,"reg=family|tmp=fresh|day=1,14|mood=funny|world=building,snow",{1,"Uncle Mack ran one off the porch with a snow shovel - in July",2,"Why does a man own a snow shovel handy in July?",3,"I never put anything away, I call that being prepared",1,"He calls the Christmas lights on the gutters being prepared too"}},
{"s1_c03_which_screw_046","any",2,"reg=family|tmp=fresh|day=3,14|mood=sad|world=door",{1,"I finished hanging the screen door, the one Gary started",2,"You don't know how to hang a screen door",1,"I know I don't, took me the whole morning - I kept turning around to ask him which screw"}},
{"s1_c03_mutter_church_shoes_047","any",1,"reg=civilian|tmp=fresh|day=1,10|mood=sad",{1,"Wore my church shoes Friday, for the Moore boy's graduation cookout",1,"Ran six miles in them, heels are gone - toes are gone",1,"Forty dollars at the mall, should have worn the sneakers"}},
{"s1_c03_lunch_cooler_048","any",3,"reg=family|tmp=fresh|day=3,14|mood=warm|world=door,window",{1,"Somebody's coming up the drive! On foot, limping!",2,"Get back from that window, get the gun",1,"It's Dad! It's Dad, he's got his lunch cooler!",3,"Nobody unbars that door till I see his arms - Earl! Earl, show me your arms!",2,"He's holding them up, he's waving his lunch cooler at us"}},
{"s1_c03_thaw_the_chicken_049","any",2,"reg=family|tmp=fresh|day=1,12|mood=sad",{1,"Last thing Mama said to me was don't forget to take the chicken out to thaw",2,"Did you?",1,"I forgot, I was at the pool - I keep thinking about that chicken"}},
{"s1_c03_wake_me_twice_050","any",2,"reg=family|tmp=fresh|day=2,12|hour=22,4|mood=fear|world=window",{1,"Your turn at the window, wake me if anything comes across the yard",2,"What if it's a person?",1,"Then wake me twice as fast",2,"What if it's Dad?",1,"Then wake me, and don't you unlock anything till I'm standing right beside you"}},
{"s1_c03_stupid_bike_051","any",3,"reg=family|tmp=fresh|day=1,12|mood=angry",{1,"It's your fault Dad went back out, you wanted your stupid bike",2,"I didn't ask him to go!",1,"You cried till he went",3,"Enough, both of you - he went because he wanted to, that was your father - he went back for things"}},
{"s1_c03_sit_with_mr_hale_052","any",3,"reg=civilian|tmp=fresh|day=0,6|hour=19,4|mood=grim",{1,"I remember sitting up with Mr. Hale till morning, in case",2,"In case he got up",1,"That's right. In case",3,"I'd sat with my own daddy before any of this. Never thought I'd be afraid to hear him move"}},
{"s1_door_gene_hollis_001","any",2,"reg=family|tmp=fresh|day=0,6|mood=fear|world=door",{1,"That's Gene Hollis, that's Gene from two doors down!",2,"I know who it is",1,"He's saying please, he's saying your name",2,"He's bleeding all over the welcome mat, too - get your hand off that deadbolt"}},
{"s1_door_duke_treeline_002","any",2,"reg=family|tmp=fresh|day=0,14|hour=21,5|mood=fear|world=trees,road",{1,"Duke's barking at the tree line again",2,"Shut him in the laundry room before he brings the whole street",1,"He never barked at nothing in his life, not once in nine years",2,"Then he's not barking at nothing"}},
{"s1_door_secret_knock_003","any",3,"reg=family|tmp=fresh|day=1,14|mood=calm|world=door",{1,"Three slow, two quick, that's the knock - anything else, nobody touches the door",2,"What if they learn it?",3,"They can't work a doorknob, Kyle",2,"Mrs. Fenton couldn't work a doorknob before either, and she got in our garage twice"}},
{"s1_door_woman_with_boy_004","any",3,"reg=civilian|tmp=fresh|day=1,12|mood=angry|world=building",{1,"She's got a little boy with her, I'm not leaving a little boy out on that porch",2,"Nobody said leave him, I said check them both first",3,"Check them how? Strip a five-year-old in the carport?",2,"Arms and ankles - gentle, then they come in, and they get my blanket"}},
{"s1_door_table_leaves_005","any",2,"reg=family|tmp=fresh|day=1,10|mood=calm",{1,"We're out of plywood, out of nails too, near about",2,"Use the leaves out of the dining table, the good oak ones",1,"Your mother gave us that table",2,"And she'd be the first one holding the hammer - go get 'em"}},
{"s1_door_watch_swap_006","any",2,"reg=civilian|tmp=fresh|day=1,14|hour=1,4|mood=calm|world=building",{1,"Your watch - anything?",2,"Two went by around midnight, one of them stopped at the mailbox a long time",1,"Reading the mail?",2,"Wish I knew - coffee's cold, wake me if it comes back"}},
{"s1_door_back_door_cat_007","any",3,"reg=family|tmp=fresh|day=1,14|hour=6,11|mood=funny|world=door",{1,"Something was scratching at the back door all night long - I didn't sleep a wink",2,"I looked this morning, it was the Tuckers' orange cat",1,"I sat up with a fireplace poker for six hours for a cat?",3,"Well, he looked real hungry, and a little bit guilty"}},
{"s1_door_polite_knock_008","any",2,"reg=civilian,family|tmp=fresh|day=2,14|hour=20,4|mood=fear",{1,"Somebody knocked, real polite, three times - then stopped",2,"Nobody polite is out walking at this hour",1,"I know, that's why I didn't answer it"}},
{"s1_door_mailman_009","any",2,"reg=family|tmp=fresh|day=1,5|mood=sad",{1,"Mail didn't run again",2,"Well, no",1,"Mr. Dotson never missed a day in twenty-two years, not for the ice storm, not for his hernia",2,"Then he's got a good reason"}},
{"s1_door_doorbell_010","any",2,"reg=civilian,family|tmp=fresh|day=1,14|mood=fear|world=inside",{1,"The doorbell's been going for ten minutes straight - ding-dong, ding-dong",2,"One of them's leaning on it, fell against it and just stayed",1,"Can we cut the wire?",2,"From in here? Be my guest, it's in the wall"}},
{"s1_door_window_face_011","any",2,"reg=family|tmp=fresh|day=1,14|hour=0,5|mood=fear|world=window,building",{1,"There was a face at the kitchen window, right up to the glass",2,"Whose face?",1,"The Morrow boy, the one that mowed our yard, he had his Walkman headphones still around his neck"}},
{"s1_door_car_alarm_012","any",3,"reg=civilian|tmp=fresh|day=0,8|mood=angry|world=vehicle,road",{1,"That car alarm's been going since supper, every one of them on this street's headed to it",2,"Good, let 'em go look at the car",3,"It's my car",2,"Then it's being very brave for us, thank it later"}},
{"s1_door_rusty_road_013","any",2,"reg=family|tmp=fresh|day=2,14|hour=4,11|mood=sad|world=road",{1,"Rusty got loose and ran down to the road, barking his head off - they all went to him",2,"Instead of the house",1,"I found his collar out by the ditch this morning - the tag still says call Wanda, and our old number"}},
{"s1_door_spigot_man_014","any",3,"reg=civilian|tmp=fresh|day=2,14|mood=warm",{1,"Man out by the side spigot just wants to fill his jug - he's got two in a wagon",2,"Tell him to go ahead, the water's still running for now",3,"He left a can of corned beef on the step when he went - didn't knock or nothing",2,"Well, guess we're even, then"}},
{"s1_door_pastor_peephole_015","any",2,"reg=family|tmp=fresh|day=1,10|mood=fear",{1,"It's Pastor Reed out there",2,"Is he, is he one of them?",1,"Hard to tell through a peephole, he's still got his collar on",2,"Ask him the name of your first dog, he buried it with you"}},
{"s1_door_hendersons_cost_016","any",2,"reg=family|tmp=fresh|day=2,12|mood=grim|world=door",{1,"If we take the Hendersons, that's four more mouths, our food barely lasts us till the twentieth as it is",2,"Ruth Henderson sat with your daddy every day at the end - every single day",1,"I know it",2,"Then open the door"}},
{"s1_door_glass_next_017","any",3,"reg=civilian,family|tmp=fresh|day=1,14|hour=21,4|mood=fear|world=building",{1,"Was that glass? Next door?",2,"Their big front window",3,"Nobody's been living there since Saturday",1,"Then what's walking around in there?"}},
{"s1_door_mutter_three_am_018","any",1,"reg=civilian,family|tmp=fresh|day=1,14|hour=2,4|mood=fear",{1,"Three-oh-six, clock on the VCR says three-oh-six",1,"Crickets stopped - why'd the crickets stop?",1,"Okay, there they go - good crickets - good boys"}},
{"s1_door_shed_lockout_019","any",2,"reg=family|tmp=fresh|day=1,14|mood=funny|world=vehicle",{1,"Who locked me in the shed? I was in there forty minutes hollering in a whisper",2,"How do you holler in a whisper?",1,"Very, very carefully, while one of 'em's reading the license plates on the car"}},
{"s1_door_garage_blame_020","any",2,"reg=family|tmp=fresh|day=1,14|mood=angry|world=door",{1,"Who left the garage door up? There's two of them in there bumping into the lawnmower",2,"I pushed the button",1,"You pushed it twice, then! Once is down, twice is up!",2,"Don't you yell at me about that button, you've been saying you'd fix it since Easter"}},
{"s1_door_its_me_021","any",3,"reg=family|tmp=fresh|day=1,14|mood=warm",{1,"Open up! It's me, it's Tommy!",2,"Tommy? Oh thank God - get in, get in!",1,"The drugstore's picked clean, I got aspirin and a whole sack of hard candy",3,"You were gone four hours for hard candy?",1,"Butterscotch, though"}},
{"s1_door_piano_022","any",4,"reg=family|tmp=fresh|day=1,10|mood=funny|world=door",{1,"On three, we push the piano against the front door",2,"That piano hasn't moved since nineteen sixty-one",3,"Nobody's played it since then either",4,"Finally gonna earn its keep",1,"One - two - mind your toes"}},
{"s1_door_dog_whine_023","any",2,"reg=family|tmp=fresh|day=3,14|mood=sad|world=door",{1,"Sadie won't come away from the side door, the one Doug went out Saturday",2,"Put her food bowl over by it, let her eat there, then",1,"I did, she won't eat either"}},
{"s1_door_flashlight_signal_024","any",3,"reg=family|tmp=fresh|day=3,14|hour=21,1|mood=warm|world=building,road",{1,"Porch across the street - see the flashlight? Two flashes",2,"That's Walt and Bev, two means they're alright",3,"Flash 'em back, two for us",1,"Every night at nine, like the evening news"}},
{"s1_door_fence_count_025","any",2,"reg=civilian|tmp=fresh|day=2,14|hour=4,11|mood=fear|world=fence",{1,"How many at the back fence now?",2,"Eleven, twelve with the one sitting down",1,"There were four this morning",2,"Stop talking so loud and it might stay twelve"}},
{"s1_door_wipe_feet_026","any",3,"reg=family|tmp=fresh|day=2,14|mood=funny|world=window",{1,"Come on, come on, through the window! Grab my hand!",2,"I'm in, I'm in, my shoe's still out there",3,"Wipe your feet - I mopped",2,"She mopped! We're under siege and she mopped!"}},
{"s1_door_roof_steps_027","any",2,"reg=civilian,family|tmp=fresh|day=1,14|hour=22,5|mood=fear|world=rooftop",{1,"Somebody's on the roof",2,"It's the maple, branches on the shingles",1,"Branches don't walk heel-toe, heel-toe",2,"Get the flashlight, don't turn it on yet"}},
{"s1_door_porch_shotgun_028","any",2,"reg=family|tmp=fresh|day=1,14|mood=warm|world=road",{1,"Mr. Kincaid's out on his porch again with his shotgun across his knees",2,"He's eighty-three",1,"He waved at me with it, then he pointed at our house and gave me a thumbs up",2,"He's watching our side of the street for us, that old goat"}},
{"s1_door_crying_next_029","any",2,"reg=family|tmp=fresh|day=2,10|mood=sad|world=building",{1,"That baby next door's been crying for three hours",2,"I know",1,"Nobody's shushing it, there's no radio, no footsteps, no nothing - just the crying",2,"Get the bat, I'll get my shoes"}},
{"s1_door_knocking_stopped_030","any",2,"reg=civilian|tmp=fresh|day=1,14|hour=20,5|mood=fear",{1,"The knocking stopped",2,"Good",1,"No, stopping means it's walking around to the back"}},
{"s1_door_wont_come_in_031","any",2,"reg=civilian|tmp=fresh|day=2,14|mood=sad",{1,"Sometimes I want to tell every stranger we'll find them a place. Even when I don't know where",2,"That's kind, I lost the house, and my Bill in it, and our girl - I'm just gonna keep walking a while",2,"You could listen a minute. That's something you can actually offer"}},
{"s1_door_dog_pack_032","any",3,"reg=civilian|tmp=fresh|day=5,14|mood=fear",{1,"Saw a pack of dogs come through the ball field - maybe eight, collars on half of 'em",2,"People's dogs, running loose",3,"Anybody's beagle can get mean hungry",1,"One of 'em was a Pomeranian - leading"}},
{"s1_door_sirens_stopped_033","any",2,"reg=civilian,family|tmp=fresh|day=3,9|mood=grim",{1,"When did you last hear a siren?",2,"Night before last, out toward the Dixie Highway",1,"The first night I couldn't sleep for all the sirens - now I can't sleep for none"}},
{"s1_door_feed_the_cat_034","any",2,"reg=family|tmp=fresh|day=1,10|mood=sad|world=door",{1,"Hal's out on his step talking to me through the door - he knows he's bit, he says he ain't coming in",2,"What's he want?",1,"Wants somebody to feed his cat, food's in the bottom cupboard, and she likes it warmed"}},
{"s1_door_teen_arms_035","any",3,"reg=civilian|tmp=fresh|day=1,14|mood=fear|world=building",{1,"Boy says he's not bit, he's shaking so hard I can hear his teeth",2,"Tell him roll up his sleeves and turn around slow under the porch light",3,"He's doing it - he's clean, he's clean, let him in!",2,"Okay, somebody get the kid a blanket and quit crowding him"}},
{"s1_door_introductions_036","any",3,"reg=civilian|tmp=fresh|day=0,4|hour=19,2|mood=calm|world=building",{1,"We never did names, we've been in this basement six hours and I don't know a one of your names",2,"Darlene, I do hair in Muldraugh",3,"Earl - retired, mostly I fish",1,"Well, Darlene and Earl, I'm real sorry we met like this"}},
{"s1_door_snoring_shifts_037","any",3,"reg=civilian|tmp=fresh|day=2,14|hour=23,5|mood=funny",{1,"We sleep in shifts, and whoever snores goes on first watch",2,"I don't snore",3,"You snore like a bass boat pulling a skier",2,"Fine, first watch, but I'm not happy about it"}},
{"s1_door_microwave_beep_038","any",2,"reg=family|tmp=fresh|day=1,14|mood=angry",{1,"Unplug the microwave, that beep goes through the whole house",2,"It's three little beeps",1,"Three little beeps is a dinner bell to them - unplug it"}},
{"s1_door_attic_ladder_039","any",2,"reg=family|tmp=fresh|day=1,14|mood=calm|world=stairs,building",{1,"If they get in downstairs, everybody goes up the attic ladder and we pull it after us",2,"It's a hundred and thirty degrees up there",1,"Then we'll be hot - put water jugs up there today"}},
{"s1_door_chain_lock_040","any",2,"reg=family|tmp=fresh|day=1,14|mood=funny|world=building",{1,"This chain lock is the one thing in this house your brother ever fixed",2,"And it's holding",1,"It's holding, I'll tell him he did good - when he gets back from wherever he's hiding"}},
{"s1_door_headlights_041","any",3,"reg=civilian,family|tmp=fresh|day=1,14|hour=21,5|mood=fear",{1,"Headlights, somebody's pulling in our driveway",2,"Army?",3,"It's a station wagon with wood on the sides",1,"The Army's not coming in a station wagon, kill the lamp"}},
{"s1_door_storm_door_042","any",2,"reg=family|tmp=fresh|day=1,14|hour=20,5|mood=calm|world=door",{1,"The storm door's rattling",2,"Wind's picked up, coming a gullywasher tonight, you can smell it",1,"I'm going to check it anyway",2,"I know you are - take the flashlight"}},
{"s1_door_grocery_gift_043","any",2,"reg=family|tmp=fresh|day=3,14|mood=warm|world=building,road",{1,"There's a grocery sack on the porch, canned peas, rice, a box of powdered milk",2,"From who?",1,"No note, just a crayon drawing of a house with a big smile on it",2,"Those Marsh kids, their mama must have sent 'em across while the street was clear"}},
{"s1_door_wind_chimes_044","any",2,"reg=civilian,family|tmp=fresh|day=2,14|mood=angry|world=building",{1,"Those wind chimes on the Tolliver porch, I'm going to go rip them down",2,"There's six of them in the Tolliver yard",1,"I hated those chimes before any of this, now I got a real reason"}},
{"s1_door_fema_man_045","any",3,"reg=civilian|tmp=fresh|day=3,12|mood=fear|world=door",{1,"Man at the door says he's with the government, says he's collecting guns for safekeeping",2,"What's he wearing?",1,"Jeans and a bowling shirt",3,"Don't open that door, tell him the guns are safe right where they are"}},
{"s1_door_cat_flap_046","any",2,"reg=family|tmp=fresh|day=1,10|mood=sad",{1,"I nailed a board over the cat flap",2,"Pumpkin's still out there somewhere",1,"I know, I left her dish on the back step - right up by the board"}},
{"s1_door_trade_through_mail_slot_047","any",2,"reg=civilian|tmp=fresh|day=3,14|mood=calm|world=door",{1,"A lady once offered batteries through our mail slot. Wanted to swap",2,"For what?",1,"Tampons, and whatever cigarettes we had",2,"I hope you didn't make her beg for the tampons just to keep your cigarettes"}},
{"s1_door_boards_sing_048","any",3,"reg=family|tmp=fresh|day=2,14|hour=20,4|mood=fear|world=window",{1,"The boards over the den window are creaking, every time one leans on 'em",2,"They'll hold",3,"You used drywall screws",2,"And they'll hold, everybody go sit in the hall"}},
{"s1_door_moving_on_049","any",2,"reg=civilian|tmp=fresh|day=4,14|hour=6,9|mood=calm|world=fence",{1,"They moved on in the night, the whole bunch at the fence",2,"Where to?",1,"Toward the school, something over there must've made a noise",2,"Poor somebody"}},
{"s1_door_hollering_name_050","any",2,"reg=family|tmp=fresh|day=1,8|hour=19,3|mood=sad|world=window,road",{1,"There's a man walking down the middle of the street hollering for somebody named Crystal",2,"He's gonna get himself killed",1,"He knows, he's been at it an hour - Crystal, it's Daddy - Crystal",2,"Shut the window, please, I can't listen to it"}},
}
